    /// <summary>
    /// Returns information about a single member of a chat
    /// </summary>
    public Task<TdLib.TdApi.Objects.ChatMember> GetChatMemberAsync(long chatId = default, MessageSender memberId = default)
    {

           using var activity =  StartCallActivity("GetChatMemberAsync", typeof(GetChatMember).FullName ?? "GetChatMemberAsync");

           try
           {
             return client.GetChatMemberAsync(chatId, memberId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
